import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.Dhf_H6O0.js";const i="/mbit-mcpo-proxy-download/guide/images/settings-advanced-config.png",p=JSON.parse('{"title":"Advanced Mode","description":"","frontmatter":{},"headers":[],"relativePath":"settings/advanced-mode.md","filePath":"settings/advanced-mode.md"}'),r={name:"settings/advanced-mode.md"};function s(d,e,l,c,h,g){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="advanced-mode" tabindex="-1">Advanced Mode <a class="header-anchor" href="#advanced-mode" aria-label="Permalink to &quot;Advanced Mode&quot;">​</a></h1><p>Advanced mode reveals additional technical details in the UI. It&#39;s intended for developers and power users.</p><h2 id="enabling-advanced-mode" tabindex="-1">Enabling Advanced mode <a class="header-anchor" href="#enabling-advanced-mode" aria-label="Permalink to &quot;Enabling Advanced mode&quot;">​</a></h2><ol><li>Go to <strong>Settings</strong>.</li><li>Under <strong>Gateway &amp; Docker</strong>, check <strong>Advanced mode</strong> (technical names, raw transport labels, generated config tools).</li></ol><h2 id="what-changes" tabindex="-1">What changes <a class="header-anchor" href="#what-changes" aria-label="Permalink to &quot;What changes&quot;">​</a></h2><h3 id="server-list" tabindex="-1">Server list <a class="header-anchor" href="#server-list" aria-label="Permalink to &quot;Server list&quot;">​</a></h3><ul><li>Transport labels switch from friendly names (like &quot;Streamable HTTP&quot;) to technical identifiers (like <code>streamable-http</code>).</li></ul><h3 id="settings-page" tabindex="-1">Settings page <a class="header-anchor" href="#settings-page" aria-label="Permalink to &quot;Settings page&quot;">​</a></h3><p>A new <strong>Generated config</strong> card appears at the bottom:</p><p><img src="'+i+'" alt="Generated config card in Advanced mode"></p><p>This card shows:</p><ul><li><strong>View Config</strong> — display the generated <code>config.json</code> that&#39;s mounted into the Docker container.</li><li><strong>Regenerate &amp; Restart</strong> — regenerate the config file from your current server definitions and restart the gateway immediately.</li></ul><p>The config preview shows the exact JSON the gateway uses, including server URLs, transport types, OAuth settings, and tool lists.</p><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><ul><li>Technical labels and identifiers are shown where friendly names would normally appear.</li></ul><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><ul><li><strong>Debugging</strong> — inspect the generated config to verify server definitions are correct.</li><li><strong>Support</strong> — share the config output with MindBehind support when troubleshooting.</li><li><strong>Development</strong> — when building custom MCP servers and you need to see the raw configuration.</li></ul><h2 id="disabling" tabindex="-1">Disabling <a class="header-anchor" href="#disabling" aria-label="Permalink to &quot;Disabling&quot;">​</a></h2><p>Uncheck the <strong>Advanced mode</strong> checkbox in Settings. The UI returns to the simplified view. No data is lost — this is purely a display toggle stored in your browser&#39;s local storage.</p>',19)])])}const m=a(r,[["render",s]]);export{p as __pageData,m as default};
